    "questionHindi": "सूचीकरण संहिता AACR-2 के नियमों के अनुसार, यदि किसी कृति की रचना चार या चार से अधिक सह-लेखकों द्वारा की गई हो और कोई प्रमुख लेखक न हो, तो मुख्य प्रविष्टि (Main Entry) किसके अंतर्गत बनेगी?",
