    "explanationHindi": "AACR-2 के नियम 21.7B के अनुसार, चार या अधिक लेखकों वाली संयुक्त रचना में मुख्य प्रविष्टि ग्रंथ की आख्या (Title) के अंतर्गत बनाई जाती है और केवल प्रथम लेखक के नाम के आगे 'et al.' जोड़कर सहायक प्रविष्टि बनती है।",
